mapper.select:
SELECT * FROM TBL_FINANCE_STATEMENT

    AND COMPANY_ID = #{query.companyId}
    AND REPORT_TYPE = #{query.reportType}
    AND REPORT_PERIOD = #{query.reportPeriod}

ORDER BY REPORT_PERIOD DESC, CREATE_TIME DESC

SELECT COMPANY_ID, COMPANY_NAME, REPORT_PERIOD, TOTAL_ASSETS, TOTAL_LIABILITIES, NET_ASSETS, REVENUE, NET_PROFIT, CASE WHEN TOTAL_ASSETS > 0 THEN ROUND(TOTAL_LIABILITIES / TOTAL_ASSETS * 100, 2) ELSE 0 END AS debtRatio, CASE WHEN REVENUE > 0 THEN ROUND(NET_PROFIT / REVENUE * 100, 2) ELSE 0 END AS profitMargin FROM TBL_FINANCE_STATEMENT
AND COMPANY_ID = #{companyId} AND REPORT_PERIOD = #{reportPeriod}
ORDER BY REPORT_PERIOD DESC
